best=(1,)
for b in np.linspace(0.1,2,40):
  for k in np.linspace(0.05,3,60):
    for j in [1,2,3]:
      f=np.tanh(b*t); g=np.exp(-k*t)
      A=np.column_stack([np.ones_like(t),f,P,P*g,P**2,P**2*g,P**3,P**3*g,P*f,P**2*f])
